content:
横版动作/格斗是高难度品类，成败全在「判定」与「状态机」是否写对。本技能只覆盖本品类独有部分（攻击判定、连招、硬直/无敌帧、格挡弹反、敌人 AI 状态机、击退、镜头）；通用结构、dt、resize、粒子/震动/浮字、start/over 界面请配合 gameloop / polish / gamedesign 技能。所有代码可直接 lift，已逐块静态运行验证。

## 0. 坐标约定（先定死，否则判定全错）

本技能所有实体的 `(x, y)` 表示**脚底中线**：`x` 是水平中心，`y` 是脚底（落地基准）。实体矩形（hurtbox）= `{x: e.x - e.w/2, y: e.y - e.h, w: e.w, h: e.h}`。统一约定后 hitbox/hurtbox 才能正确重叠。攻击朝向用 `facing`（`1` 右 / `-1` 左）。

```javascript
function clamp(v, lo, hi) { return v < lo ? lo : (v > hi ? hi : v); }

// 标准 AABB 矩形重叠（攻击判定与受击判定都用它）
function aabb(a, b) {
  return a.x < b.x + b.w && a.x + a.w > b.x &&
         a.y < b.y + b.h && a.y + a.h > b.y;
}

// 实体受击框（hurtbox）：以脚底中线为原点
function hurtbox(e) {
  return { x: e.x - e.w / 2, y: e.y - e.h, w: e.w, h: e.h };
}
```

## 1. 攻击生命周期：startup / active / recovery（动作游戏的灵魂）

每次攻击分三段：前摇(startup)→ 出招(active，**仅此段有 hitbox**)→ 后摇(recovery，不可取消)。用秒计时、全乘 dt。**一次挥击只能命中同一目标一次**，靠 `hitSet` 记录已命中 id，在 `startAttack` 时新建、攻击结束清空——这是对象/集合复用最容易写错的地方（忘了清空会导致下一击打不出或重复命中）。

```javascript
// 连招表：每段招式数据。最后一段 window=0 表示连招到此结束
const ATTACKS = [
  { startup: 0.08, active: 0.06, recovery: 0.18, reach: 46, hh: 36, dmg: 8,  kb: 160, window: 0.35 },
  { startup: 0.10, active: 0.07, recovery: 0.20, reach: 50, hh: 38, dmg: 10, kb: 200, window: 0.35 },
  { startup: 0.14, active: 0.10, recovery: 0.34, reach: 60, hh: 48, dmg: 18, kb: 420, window: 0    },
];

// 攻击命中框：随 facing 翻转。reach 是从身体边缘往前伸的长度
function playerHitbox(p) {
  const atk = p._curAtk;
  const hw = atk.reach;
  const hx = p.facing === 1 ? p.x + p.w / 2 : p.x - p.w / 2 - hw; // 左挥时整体左移 hw
  const hy = p.y - p.h * 0.75 - atk.hh * 0.5;                     // 大致打在上半身高度
  return { x: hx, y: hy, w: hw, h: atk.hh, dmg: atk.dmg, kb: atk.kb };
}

function startAttack(p) {
  if (p.hitstun > 0) return;                              // 硬直中不能出招
  if (p.attackPhase && p.attackPhase !== 'recovery') return; // 前摇/出招中不可打断
  if (p.comboTimer <= 0) p.comboStep = 0;                // 连招窗口已过→从头
  p._curAtk = ATTACKS[Math.min(p.comboStep, ATTACKS.length - 1)];
  p.attackPhase = 'startup';
  p.attackTime = 0;
  p.hitSet = new Set();                                   // ✅ 每次挥击新建，防重复命中
  p.state = 'attack';
}

function updateAttack(p, dt, targets) {
  if (!p.attackPhase) return;
  const atk = p._curAtk;
  p.attackTime += dt;
  if (p.attackPhase === 'startup') {
    if (p.attackTime >= atk.startup) { p.attackPhase = 'active'; p.attackTime -= atk.startup; }
  } else if (p.attackPhase === 'active') {
    const hb = playerHitbox(p);
    for (const e of targets) {
      if (e.dead || p.hitSet.has(e.id)) continue;         // ✅ 这一挥已打过它→跳过
      if (aabb(hb, hurtbox(e))) {
        p.hitSet.add(e.id);
        applyHit(e, hb.dmg, hb.kb, p.facing);
        onHitFx(hb.x + hb.w / 2, hb.y + hb.h / 2);        // 命中反馈：见 polish 技能
      }
    }
    if (p.attackTime >= atk.active) { p.attackPhase = 'recovery'; p.attackTime -= atk.active; }
  } else { // recovery
    if (p.attackTime >= atk.recovery) {
      p.attackPhase = null;
      p.state = 'idle';
      p.comboStep = Math.min(p.comboStep + 1, ATTACKS.length - 1); // 推进连招
      p.comboTimer = atk.window;                          // 开启下一招的输入窗口
    }
  }
}

function onHitFx(x, y) { screenShake(6, 0.12); spawnParticles(x, y, 8, '#ffcf4d'); /* 见 polish */ }
```

## 2. 连招输入窗口

`comboTimer` 在每段攻击结束时设为该段的 `window`，之后逐帧 `-= dt`；归零则连招重置。**注意 `<= 0` 判定**（用 `>` 会漏掉刚好为 0 的帧）。在玩家计时器统一更新里处理：

```javascript
function updatePlayerTimers(p, dt) {
  p.invuln    = Math.max(0, p.invuln - dt);
  p.parryTimer = Math.max(0, p.parryTimer - dt);
  if (p.comboTimer > 0) { p.comboTimer -= dt; if (p.comboTimer <= 0) p.comboStep = 0; }
  if (p.hitstun > 0) {
    p.hitstun -= dt;
    p.vx *= Math.pow(0.0001, dt);                         // ✅ dt 相关的指数衰减，非 *=0.9
    if (p.hitstun <= 0) p.state = 'idle';
  }
}
```

## 3. 受击：硬直(hitstun) + 无敌帧(i-frame) + 击退(knockback)

`applyHit` 是唯一改血的入口。先查无敌帧（无敌中直接忽略，**这是防止一次攻击多段误伤、连续秒杀的关键**），再查格挡/弹反，再结算伤害、击退、硬直、并赋予短暂无敌（受击后的“喘息帧”）。击退方向 = 攻击者 `facing`，速度存入 `vx` 后随硬直衰减——绝不写成瞬移。

```javascript
function applyHit(t, dmg, kb, dir) {
  if (t.invuln > 0) return;                               // ✅ 无敌帧：整次命中作废
  if (t.blocking && t.facing === -dir) {                  // 必须面朝攻击来源才算挡住
    if (t.parryTimer > 0) {                               // 弹反窗口内→完全格挡并反击
      t.parried = true;
      return;                                             // 不掉血、不击退、不硬直
    }
    dmg *= 0.2; kb *= 0.4;                                // 普通格挡：减伤减退
  }
  t.hp -= dmg;
  t.vx = kb * dir;                                        // 击退入速度，逐帧衰减
  t.hitstun = Math.max(t.hitstun, 0.25);                 // 硬直取较大值，不被小招打断刷新
  t.invuln  = 0.12;                                       // 受击后短无敌
  t.state = 'hitstun';
  if (t.hp <= 0) { t.hp = 0; t.dead = true; }
}
```

弹反成功后由攻击发起方读取 `t.parried` 做反击（让攻击者进入长硬直 / 玩家获得反击窗口），读后清掉标志位。

## 4. 敌人 AI 状态机（巡逻 / 接近 / 攻击 / 受击）

用 `switch(e.state)` 显式列全状态，**必须带 `default` 兜底**回到 `patrol`，否则脏数据会让敌人卡死（漏状态是 FSM 头号 bug）。每个状态自带 `stateTime` 累计，攻击有冷却 `atkCd`。受击优先级最高，先于 switch 处理，硬直结束才放行回 `patrol`。

```javascript
function updateEnemy(e, dt, p) {
  if (e.dead) return;
  e.invuln = Math.max(0, e.invuln - dt);
  e.atkCd  = Math.max(0, e.atkCd  - dt);

  // 受击最高优先：硬直期间只衰减速度、冻结 AI
  if (e.hitstun > 0) {
    e.hitstun -= dt;
    e.vx *= Math.pow(0.0001, dt);
    e.x += e.vx * dt; e.x = clamp(e.x, 20, WORLD_W - 20);
    if (e.hitstun <= 0) e.state = 'patrol';
    return;
  }

  const dist  = p.x - e.x;       // 带符号：>0 玩家在右
  const adist = Math.abs(dist);

  switch (e.state) {
    case 'patrol':
      e.vx = 40 * e.patrolDir;
      e.stateTime += dt;
      if (e.stateTime > 2) { e.patrolDir *= -1; e.stateTime = 0; } // 来回踱步
      if (adist < 260) { e.state = 'approach'; e.stateTime = 0; }  // 发现玩家
      break;
    case 'approach':
      e.facing = dist >= 0 ? 1 : -1;
      e.vx = 95 * e.facing;
      if (adist < 56)      { e.state = 'attack';  e.stateTime = 0; e.vx = 0; }
      else if (adist > 320){ e.state = 'patrol';  e.stateTime = 0; }          // 跟丢
      break;
    case 'attack':
      e.vx = 0;
      e.stateTime += dt;
      if (e.atkCd <= 0 && e.stateTime > 0.22) {                    // 0.22s 前摇给玩家反应
        const hb = { x: e.facing === 1 ? e.x + e.w / 2 : e.x - e.w / 2 - 40,
                     y: e.y - e.h * 0.7, w: 40, h: 30 };
        if (aabb(hb, hurtbox(p))) applyHit(p, 6, 140, e.facing);
        e.atkCd = 1.2; e.stateTime = 0;
      }
      if (adist > 72) { e.state = 'approach'; e.stateTime = 0; }   // 玩家拉开→重新接近
      break;
    default:
      e.state = 'patrol';                                          // ✅ 兜底，永不卡死
  }

  e.x += e.vx * dt;
  e.x = clamp(e.x, 20, WORLD_W - 20);
}
```

难度提升（配合 gamedesign）：随 `getDifficulty()` 调高敌人 `speed`、缩短 `atkCd`、加快出招前摇。

## 5. 镜头跟随（横版必备）

镜头 dt 平滑插值跟随玩家并**夹紧到世界边界**（防止露出世界外的空白）。绘制世界时 `save → translate(-camX,-camY) → 画实体 → restore`，**save/restore 必须配对**，否则变换会累积导致画面漂移。HUD/界面在 restore 之后用屏幕坐标画（不跟镜头动）。

```javascript
let camX = 0, camY = 0;
const WORLD_W = 2400;
function updateCamera(dt) {
  const target = clamp(player.x - canvas.width * 0.4, 0, Math.max(0, WORLD_W - canvas.width));
  camX += (target - camX) * Math.min(1, dt * 6);          // ✅ dt 平滑，min(1,...) 防过冲
}
function drawWorld() {
  ctx.save();
  ctx.translate(-camX, -camY);
  drawBackground(); drawEnemies(); drawPlayer(); drawParticles();
  ctx.restore();                                          // ✅ 与 save 配对
  drawHUD();                                              // 屏幕坐标，不受镜头影响
}
// 世界坐标→屏幕坐标（做屏幕特效/点击命中时用）：sx = wx - camX
```

## 6. 触摸 + 键盘输入（手机为主）

虚拟按键（移动/攻击/格挡）按屏幕区域划分。触摸坐标必须按 `canvas.width/rect.width` 换算；`touchstart/touchmove` 加 `preventDefault()` 且 `{passive:false}`，否则会触发页面滚动/缩放。

```javascript
const rect0 = () => canvas.getBoundingClientRect();
function toCanvas(clientX, clientY) {
  const r = rect0();
  return { x: (clientX - r.left) * (canvas.width / r.width),
           y: (clientY - r.top)  * (canvas.height / r.height) };
}
function handleTouch(e) {
  e.preventDefault();                                     // ✅ {passive:false} 才生效
  if (state !== 'playing') { if (state === 'start' || state === 'over') resetGame(); return; }
  let move = 0, atk = false, block = false;
  for (const t of e.touches) {
    const p = toCanvas(t.clientX, t.clientY);
    if (p.x < canvas.width * 0.25)      move = -1;        // 左 1/4：左移
    else if (p.x < canvas.width * 0.5)  move = 1;         // 左 2/4：右移
    else if (p.x < canvas.width * 0.75) atk = true;       // 右 2/4：攻击
    else                                block = true;     // 右 1/4：格挡
  }
  player.moveDir = move;
  player.blocking = block;
  if (block && !player._wasBlock) player.parryTimer = 0.12; // 按下瞬间开弹反窗口
  player._wasBlock = block;
  if (atk && !player._wasAtk) startAttack(player);          // 边沿触发，防长按连发
  player._wasAtk = atk;
}
canvas.addEventListener('touchstart', handleTouch, { passive: false });
canvas.addEventListener('touchmove',  handleTouch, { passive: false });
canvas.addEventListener('touchend',   handleTouch, { passive: false });
// 键盘辅助：←→ 移动，J 攻击，K 格挡（同样用 keydown 边沿触发 startAttack / parryTimer）
```

## 7. 实体绘制中的安全细节

绘制血条、攻击特效用径向渐变时，半径用 `Math.max(1, r)` 防负值报错；血条宽度按 `Math.max(0, hp/maxHp)` 夹住。删除死亡敌人 / 失效粒子一律 `filter`，**禁止在 for 循环里 splice**（会跳过元素 / 越界）：

```javascript
enemies = enemies.filter(e => !e.dead || e.deathT > 0); // 想播死亡动画就留一会
function drawHpBar(e) {
  const w = e.w, ratio = Math.max(0, e.hp / e.maxHp);
  ctx.fillStyle = '#400'; ctx.fillRect(e.x - w/2, e.y - e.h - 10, w, 4);
  ctx.fillStyle = '#f55'; ctx.fillRect(e.x - w/2, e.y - e.h - 10, w * ratio, 4);
}
```

## 8. 帧序提醒（接 gameloop 主循环）

每帧顺序固定：① `updatePlayerTimers` ② 读输入设 `player.vx` ③ 玩家位移并夹边界 ④ `updateAttack(player, dt, enemies)` ⑤ `updateEnemy` 逐个 ⑥ 清死亡/掩埋 ⑦ `updateParticles/floatTexts` ⑧ `updateCamera` ⑨ `drawWorld`。判定（④⑤）必须在位移之后，保证用的是当前帧位置。

平台跳跃品类的承重逻辑全在「物理 + 碰撞 + 手感」。通用的 canvas/resize/DPR/主循环/粒子/震动/start-over/HUD 见 `gameloop`·`polish`·`gamedesign` 三个技能，**本技能不重复样板**，只给平台跳跃独有、且容易写错的部分。下面所有代码都已静态推演过边界，可直接 lift。

## 0. 物理常量与玩家对象（像素/秒，全部配合 dt）

```javascript
// 常量单位都是 像素/秒 或 像素/秒²，移动时一律乘 dt
const GRAVITY   = 2000;   // 重力加速度
const MOVE_SPD  = 260;    // 水平移动速度
const JUMP_VY   = -720;   // 起跳初速度（向上为负）
const MAX_FALL  = 1200;   // 下落速度上限，防穿透
const COYOTE    = 0.10;   // 离开地面后仍可跳的宽限（秒）
const JUMP_BUF  = 0.12;   // 落地前提前按跳，落地立即触发（秒）
const CUT_MULT  = 0.40;   // 松开跳跃键时，上升速度衰减系数（可变跳跃高度）

let player, solids, camX, camY, levelW, levelH, gameTime;

function makePlayer(x, y) {
  return {
    x, y, w: 28, h: 36,
    vx: 0, vy: 0,
    onGround: false,
    coyote: 0,      // 还能 coyote 跳的剩余时间
    jumpBuf: 0,     // jump buffer 剩余时间
    ridingDx: 0, ridingDy: 0, // 被移动平台带走的位移，下一帧补给玩家
  };
}
```

## 1. AABB 检测（品类核心，务必这一版）

```javascript
// 标准 AABB 重叠：四个方向都相交才算碰。边贴边(===)不算碰，避免落地后又被判穿墙
function aabb(a, b) {
  return a.x < b.x + b.w && a.x + a.w > b.x &&
         a.y < b.y + b.h && a.y + a.h > b.y;
}
```

## 2. 分轴碰撞解算（先 X 后 Y，平台跳跃绝对正确写法）

为什么分轴：一次性同时移动 x、y 再解算，会无法判断该往哪个方向推出去（会出现“爬墙”“卡角”）。**先只动 x、立刻解算 x；再只动 y、立刻解算 y**，每轴的推出方向由该轴速度符号决定，干净且无歧义。

```javascript
function moveAndCollide(p, solids, dt) {
  const wasOnGround = p.onGround;
  p.onGround = false;

  // ① 被移动平台携带的位移，必须在玩家自身移动“之前”补上，
  //    这样若平台把人推向墙，后面的碰撞解算会正确把人推回来。
  p.x += p.ridingDx; p.y += p.ridingDy;
  p.ridingDx = 0; p.ridingDy = 0;

  // ② X 轴：先动 x，再逐个解算（单向平台不参与水平阻挡）
  p.x += p.vx * dt;
  for (const s of solids) {
    if (s.oneWay) continue;            // 单向平台只挡“从上往下落”，不挡左右
    if (aabb(p, s)) {
      if (p.vx > 0)      p.x = s.x - p.w;     // 向右撞，贴左边
      else if (p.vx < 0) p.x = s.x + s.w;     // 向左撞，贴右边
      p.vx = 0;
    }
  }

  // ③ Y 轴：先记下移动“之前”的脚底（单向平台判定要用），再动 y
  const prevBottom = p.y + p.h;
  p.y += p.vy * dt;
  for (const s of solids) {
    if (s.oneWay) {
      if (p.vy < 0) continue;          // 向上时穿过单向平台
      if (prevBottom > s.y) continue;  // 移动前脚底已在平台面以下/之内 → 不挡（防从下往上顶住）
    }
    if (aabb(p, s)) {
      if (p.vy > 0) {                  // 下落撞到 → 落地
        p.y = s.y - p.h;
        p.onGround = true;
        if (s.dx) p.ridingDx = s.dx;   // 站上移动平台 → 记录它这帧的位移，下一帧带走玩家
        if (s.dy) p.ridingDy = s.dy;
      } else if (p.vy < 0) {           // 上升撞到 → 顶头
        p.y = s.y + s.h;
      }
      p.vy = 0;
    }
  }

  // ④ coyote：在地面上 / 这一帧刚走下平台 都刷新宽限
  if (p.onGround || wasOnGround) p.coyote = COYOTE;
}
```

边界已验证：①从下往上穿单向平台不会被顶住；②从上方落到单向平台正常站住；③站在水平移动平台上人随平台同步移动（位移完全一致）；④大 dt（被主循环 cap 到 0.05）单帧不穿地。

## 3. 跳跃手感：重力 + coyote + jump buffer + 可变跳跃高度

```javascript
// input: {left,right,jumpHeld, jumpPressed(本帧刚按下), jumpReleased(本帧刚松开)}
function updatePlayer(p, input, dt) {
  // 水平输入（注意：不乘 dt，这是速度本身；位移在 moveAndCollide 里 *dt）
  p.vx = (input.right ? MOVE_SPD : 0) - (input.left ? MOVE_SPD : 0);

  // 重力 + 下落上限
  p.vy += GRAVITY * dt;
  if (p.vy > MAX_FALL) p.vy = MAX_FALL;

  // 计时器衰减（全部乘 dt）
  p.coyote  = Math.max(0, p.coyote  - dt);
  p.jumpBuf = Math.max(0, p.jumpBuf - dt);
  if (input.jumpPressed) p.jumpBuf = JUMP_BUF; // 落地前提前按，缓冲一小段

  // 触发跳跃：有缓冲 且 (在地面 或 coyote 窗口内)
  if (p.jumpBuf > 0 && (p.onGround || p.coyote > 0)) {
    p.vy = JUMP_VY;
    p.jumpBuf = 0; p.coyote = 0; p.onGround = false;
    // 触发处可调 polish：spawnParticles(p.x+p.w/2, p.y+p.h, 6, '#fff');
  }

  // 可变跳跃高度：上升途中松手就削上升速度（短按矮跳，长按高跳）
  if (input.jumpReleased && p.vy < JUMP_VY * CUT_MULT) {
    p.vy = JUMP_VY * CUT_MULT;
  }

  moveAndCollide(p, solids, dt);

  // 掉出关卡底部 → 死亡（接入你的 state='over'）
  if (p.y > levelH + 100) { state = 'over'; }
}
```

要点：`jumpPressed`/`jumpReleased` 是“边沿”（本帧刚发生），不是“按住”。键盘用 keydown 的 `e.repeat` 过滤重复；触摸用按下/抬起两个事件分别置位，每帧 update 末尾清掉边沿标志（见第 6 节）。

## 4. 镜头跟随 + 关卡边界 clamp

```javascript
// 摄像机平滑追玩家，并 clamp 在关卡内，避免拍到关卡外的黑边
function updateCamera(p, dt) {
  const targetX = p.x + p.w / 2 - canvas.width  / 2 / (window.devicePixelRatio || 1) * 0; // 见下注
  // 注：因为我们用 setTransform(dpr,...) 做了 DPR，绘制坐标用 CSS 像素，
  //     视口宽高用 canvas.width/dpr。这里取一次：
  const dpr = window.devicePixelRatio || 1;
  const viewW = canvas.width / dpr, viewH = canvas.height / dpr;

  let tx = p.x + p.w / 2 - viewW / 2;
  let ty = p.y + p.h / 2 - viewH / 2;
  // clamp 到关卡范围
  tx = Math.max(0, Math.min(tx, Math.max(0, levelW - viewW)));
  ty = Math.max(0, Math.min(ty, Math.max(0, levelH - viewH)));
  // 平滑追（指数缓动，乘 dt 保证不同帧率一致）
  const k = Math.min(1, dt * 8);
  camX += (tx - camX) * k;
  camY += (ty - camY) * k;
}

// 绘制时：先 ctx.save(); ctx.translate(-camX, -camY); 画世界; ctx.restore(); 再画 HUD（HUD 不跟镜头）
function draw() {
  const dpr = window.devicePixelRatio || 1;
  ctx.clearRect(0, 0, canvas.width, canvas.height); // clear 用物理像素
  ctx.save();
  ctx.translate(-camX, -camY);
  // —— 这里画平台、玩家、敌人、粒子（世界坐标）——
  for (const s of solids) {
    ctx.fillStyle = s.oneWay ? '#6a8' : '#556';
    ctx.fillRect(s.x, s.y, s.w, s.h);
  }
  ctx.fillStyle = '#4cf';
  ctx.fillRect(player.x, player.y, player.w, player.h);
  ctx.restore();
  drawHUD(); // HUD 固定在屏幕（见 gamedesign 技能）
}
```

镜头 clamp 用 `Math.max(0, levelW - viewW)`：当关卡比视口窄时不会出现负的滚动范围。

## 5. 移动平台（载人，已与碰撞解算对齐）

```javascript
// 移动平台每帧先移动并把“本帧位移”记到 s.dx / s.dy，
// 供 moveAndCollide 在判定落地时读取（玩家下一帧被带走）。
function updatePlatforms(solids, dt) {
  for (const s of solids) {
    if (!s.move) { s.dx = 0; s.dy = 0; continue; }
    const ox = s.x, oy = s.y;
    s.move.t += dt;
    // 在 [from,to] 之间往返：用三角函数得到平滑往返
    const u = (Math.sin(s.move.t * s.move.spd) + 1) / 2; // 0..1
    s.x = s.move.x0 + (s.move.x1 - s.move.x0) * u;
    s.y = s.move.y0 + (s.move.y1 - s.move.y0) * u;
    s.dx = s.x - ox; // 本帧位移
    s.dy = s.y - oy;
  }
}
// 平台定义示例：
// { x:400,y:350,w:120,h:16, oneWay:false,
//   move:{ x0:400,x1:560,y0:350,y1:350, spd:1.5, t:0 } }   // 水平移动
// 垂直移动平台同理设 y0≠y1。竖直平台把人往上顶时，ridingDy 会让人跟上去。

// 调用顺序（在 update 里）：
function update(dt) {
  gameTime += dt;
  updatePlatforms(solids, dt);  // ① 先移动平台、算出 s.dx/s.dy
  updatePlayer(player, input, dt); // ② 再更新玩家（内部读 s.dx 携带、并做碰撞）
  updateCamera(player, dt);     // ③ 镜头最后追
  // polish：updateParticles(dt); updateFloatTexts(dt); 见 polish 技能
  clearInputEdges(input);       // ④ 清掉本帧的 jumpPressed/jumpReleased 边沿
}
```

顺序很关键：**平台先动 → 玩家再动**。反了会差一帧、人会“抖”在平台上。

## 6. 输入：触摸为主、键盘为辅（边沿正确处理）

```javascript
const input = { left:false, right:false, jumpHeld:false, jumpPressed:false, jumpReleased:false };

function clearInputEdges(i) { i.jumpPressed = false; i.jumpReleased = false; } // 每帧 update 末尾调用

// —— 键盘（辅）——
addEventListener('keydown', e => {
  if (e.repeat) return;                 // 过滤系统重复，保证 jumpPressed 只触发一次
  if (e.code === 'ArrowLeft')  input.left  = true;
  if (e.code === 'ArrowRight') input.right = true;
  if (e.code === 'Space' || e.code === 'ArrowUp') {
    if (!input.jumpHeld) input.jumpPressed = true;
    input.jumpHeld = true;
  }
});
addEventListener('keyup', e => {
  if (e.code === 'ArrowLeft')  input.left  = false;
  if (e.code === 'ArrowRight') input.right = false;
  if (e.code === 'Space' || e.code === 'ArrowUp') {
    input.jumpHeld = false; input.jumpReleased = true;
  }
});

// —— 触摸（主）：屏幕左半=方向（按住点的左右决定走向），右半=跳 ——
// 触摸坐标必须按 canvas.width/rect.width 换算到 CSS 像素再判断（这里只判左右半屏，用 clientX/rect 即可）
function touchAt(e) {
  const rect = canvas.getBoundingClientRect();
  const dpr = window.devicePixelRatio || 1;
  const viewW = canvas.width / dpr;
  for (const t of e.touches) {
    const cx = (t.clientX - rect.left) * (canvas.width / rect.width) / dpr; // → CSS 像素
    return cx; // 取第一个触点即可做左右半屏判定
  }
  return null;
}
function applyTouch(e) {
  input.left = input.right = false;
  const rect = canvas.getBoundingClientRect();
  const dpr = window.devicePixelRatio || 1;
  const viewW = canvas.width / dpr;
  let wantJump = false;
  for (const t of e.touches) {
    const cx = (t.clientX - rect.left) * (canvas.width / rect.width) / dpr;
    if (cx < viewW * 0.5) {            // 左半屏：再分左右 1/4 控方向
      if (cx < viewW * 0.25) input.left = true; else input.right = true;
    } else {
      wantJump = true;                 // 右半屏：跳
    }
  }
  if (wantJump && !input.jumpHeld) input.jumpPressed = true;
  if (!wantJump && input.jumpHeld)  input.jumpReleased = true;
  input.jumpHeld = wantJump;
}
canvas.addEventListener('touchstart', e => {
  e.preventDefault();
  if (state === 'start' || state === 'over') { resetGame(); return; }
  applyTouch(e);
}, { passive: false });
canvas.addEventListener('touchmove', e => { e.preventDefault(); applyTouch(e); }, { passive: false });
canvas.addEventListener('touchend',  e => { e.preventDefault(); applyTouch(e); }, { passive: false });
```

注意 touchend 也要 `applyTouch`，因为 `e.touches` 是“当前仍按住”的触点；松开后会自动把对应方向/跳跃复位，并正确产生 `jumpReleased` 边沿（支撑可变跳跃高度）。

