## 二、承重代码（已用 node 验证算法正确，可直接 lift）

> 约定：逻辑网格 `grid` 是长度 `ROWS*COLS` 的一维数组，元素是 `0..TYPES-1` 的颜色类型，`EMPTY = -1` 表示空。`idx(r,c)=r*COLS+c`。表现层每个格子另存 `tiles[i] = { type, px, py, ... }` 用于缓动绘制，但**所有判定只看 `grid`**。

### 1. 网格基础 + 初始棋盘（无开局三连）

```javascript
const COLS = 8, ROWS = 8, TYPES = 5, EMPTY = -1;
const COLORS = ['#ff5d73', '#ffc857', '#4ade80', '#38bdf8', '#a78bfa']; // TYPES 个

const idx = (r, c) => r * COLS + c;
const inBounds = (r, c) => r >= 0 && r < ROWS && c >= 0 && c < COLS;

// 生成不含立即三连的棋盘：放每格时避免和已放置的左两格 / 上两格同色
function makeBoard() {
  const grid = new Array(ROWS * COLS).fill(EMPTY);
  for (let r = 0; r < ROWS; r++) {
    for (let c = 0; c < COLS; c++) {
      let t;
      for (let tries = 0; tries < 20; tries++) {
        t = Math.floor(Math.random() * TYPES);
        const bad =
          (c >= 2 && grid[idx(r, c - 1)] === t && grid[idx(r, c - 2)] === t) ||
          (r >= 2 && grid[idx(r - 1, c)] === t && grid[idx(r - 2, c)] === t);
        if (!bad) break;
      }
      grid[idx(r, c)] = t;
    }
  }
  // 极少数情况下仍可能无合法移动：洗到可玩为止
  if (!hasValidMove(grid)) reshuffle(grid);
  return grid;
}
```

### 2. 匹配检测（横/竖连续 ≥3，忽略 EMPTY）— 最关键

```javascript
// 返回所有"属于某条 >=3 连续段"的格子索引集合（Set）
// 写法要点：内层循环走到 <= 末尾，用"段结束"事件冲刷出末段；EMPTY 不参与
function findMatches(grid) {
  const matched = new Set();

  // 横向
  for (let r = 0; r < ROWS; r++) {
    let runStart = 0;
    for (let c = 1; c <= COLS; c++) {
      const same = c < COLS &&
        grid[idx(r, c)] !== EMPTY &&
        grid[idx(r, c)] === grid[idx(r, runStart)];
      if (!same) {                       // 段在此结束（含走到行尾）
        const runLen = c - runStart;
        if (grid[idx(r, runStart)] !== EMPTY && runLen >= 3) {
          for (let k = runStart; k < c; k++) matched.add(idx(r, k));
        }
        runStart = c;
      }
    }
  }

  // 竖向（结构完全对称）
  for (let c = 0; c < COLS; c++) {
    let runStart = 0;
    for (let r = 1; r <= ROWS; r++) {
      const same = r < ROWS &&
        grid[idx(r, c)] !== EMPTY &&
        grid[idx(r, c)] === grid[idx(runStart, c)];
      if (!same) {
        const runLen = r - runStart;
        if (grid[idx(runStart, c)] !== EMPTY && runLen >= 3) {
          for (let k = runStart; k < r; k++) matched.add(idx(k, c));
        }
        runStart = r;
      }
    }
  }

  return matched; // L 形/十字形交叉处会自然被横竖两遍共同加入，Set 自动去重
}
```

### 3. 重力下落 + 顶部补充（每列一个写指针）

```javascript
// 把每列非空格子压到底部，返回 [{fromR,toR,c}] 供表现层做下落缓动
function applyGravity(grid) {
  const moves = [];
  for (let c = 0; c < COLS; c++) {
    let writeRow = ROWS - 1;               // 从底往上的写指针
    for (let r = ROWS - 1; r >= 0; r--) {
      if (grid[idx(r, c)] !== EMPTY) {
        if (writeRow !== r) {
          grid[idx(writeRow, c)] = grid[idx(r, c)];
          grid[idx(r, c)] = EMPTY;
          moves.push({ fromR: r, toR: writeRow, c });
        }
        writeRow--;
      }
    }
  }
  return moves; // 落地后 writeRow..0 这些行就是需要补新格的空位
}

// 顶部补充：所有仍为 EMPTY 的格子填新随机色，返回新生成位置（表现层让它们从画面上方落入）
function refill(grid) {
  const spawned = [];
  for (let c = 0; c < COLS; c++) {
    for (let r = 0; r < ROWS; r++) {
      if (grid[idx(r, c)] === EMPTY) {
        grid[idx(r, c)] = Math.floor(Math.random() * TYPES);
        spawned.push({ r, c });
      }
    }
  }
  return spawned;
}
```

### 4. 合法移动检测 + 洗牌（无可消时）

```javascript
// 非破坏性：交换→检测→还原。判断这一步交换是否能产生匹配
function swapMakesMatch(grid, r1, c1, r2, c2) {
  const a = grid[idx(r1, c1)], b = grid[idx(r2, c2)];
  grid[idx(r1, c1)] = b; grid[idx(r2, c2)] = a;
  const ok = findMatches(grid).size > 0;
  grid[idx(r1, c1)] = a; grid[idx(r2, c2)] = b;   // 务必还原
  return ok;
}

// 全盘是否存在任一合法移动（只需检查向右、向下两个方向即覆盖所有相邻对）
function hasValidMove(grid) {
  for (let r = 0; r < ROWS; r++) {
    for (let c = 0; c < COLS; c++) {
      if (c + 1 < COLS && swapMakesMatch(grid, r, c, r, c + 1)) return true;
      if (r + 1 < ROWS && swapMakesMatch(grid, r, c, r + 1, c)) return true;
    }
  }
  return false;
}

// 洗牌：原地 Fisher-Yates 打乱已有格子，直到"无立即匹配 且 有合法移动"；上限兜底
function reshuffle(grid) {
  for (let attempt = 0; attempt < 200; attempt++) {
    for (let i = grid.length - 1; i > 0; i--) {
      const j = (Math.random() * (i + 1)) | 0;
      const t = grid[i]; grid[i] = grid[j]; grid[j] = t;
    }
    if (findMatches(grid).size === 0 && hasValidMove(grid)) return true;
  }
  return false; // 极端兜底：按设计可在此判负
}
```

### 5. 连锁 cascade 解算（逻辑层一次性算清，配合表现层分步播放）

```javascript
// 纯逻辑解算：返回每一层连锁的步骤，供主循环按 phase 逐层播放动画
// 每个 step：{ cleared:Set, gravity:moves, spawned:[...], chain:N }
function resolveCascade(grid) {
  const steps = [];
  let chain = 0;
  while (true) {
    const cleared = findMatches(grid);
    if (cleared.size === 0) break;        // 连锁结束
    chain++;
    cleared.forEach(i => { grid[i] = EMPTY; });
    const gravity = applyGravity(grid);
    const spawned = refill(grid);
    steps.push({ cleared, gravity, spawned, chain });
    if (chain > 100) break;               // 死循环兜底（正常永远到不了）
  }
  return steps; // steps.length === 连锁层数；空数组表示这次交换无效
}

// 连锁计分：第 N 层连锁里消除 k 个 → 得分 k * BASE * chainMultiplier(N)
function chainMultiplier(chain) { return 1 + (chain - 1) * 0.5; } // 1, 1.5, 2, 2.5...
function scoreForStep(step, BASE = 30) {
  return Math.round(step.cleared.size * BASE * chainMultiplier(step.chain));
}
```

### 6. 表现层：交换/下落/消除的 dt 缓动 + 平滑分数（已验证帧率无关）

```javascript
// ---- 缓动函数 ----
const easeOutCubic = p => 1 - Math.pow(1 - p, 3);
function easeOutBounce(p) {                 // 下落砸地的回弹
  const n1 = 7.5625, d1 = 2.75;
  if (p < 1 / d1) return n1 * p * p;
  if (p < 2 / d1) return n1 * (p -= 1.5 / d1) * p + 0.75;
  if (p < 2.5 / d1) return n1 * (p -= 2.25 / d1) * p + 0.9375;
  return n1 * (p -= 2.625 / d1) * p + 0.984375;
}
const lerp = (a, b, p) => a + (b - a) * p;

// ---- 像素坐标 ----
let cell = 40, originX = 0, originY = 0;     // 在 resize() 里按画布宽度算 cell，并居中
const cellX = c => originX + c * cell;
const cellY = r => originY + r * cell;

// ---- 一个"活动动画"对象（交换/下落/消除消失共用一套 progress 模型）----
// anim = { kind:'swap'|'drop'|'clear', t:0, dur:0.18, items:[...] }
function stepAnim(anim, dt) {
  anim.t += dt;                              // ✅ 乘 dt，禁止固定步进
  const p = Math.min(1, anim.t / anim.dur);
  return p;                                  // 返回原始进度，绘制时再套缓动
}

// 绘制一个移动中的格子：从 (fr,fc) 缓动到 (tr,tc)
function drawMovingTile(type, fr, fc, tr, tc, p, ease) {
  const e = ease(p);
  const x = lerp(cellX(fc), cellX(tc), e);
  const y = lerp(cellY(fr), cellY(tr), e);
  drawGem(type, x, y, cell);
}

// 绘制单个宝石（圆角块 + 高光，失败降级纯色），半径用 Math.max 防 0
function drawGem(type, x, y, size) {
  const pad = size * 0.12, s = size - pad * 2;
  const r = Math.max(1, s * 0.28);
  ctx.fillStyle = COLORS[type] || '#888';
  roundRect(x + pad, y + pad, s, s, r); ctx.fill();
  ctx.fillStyle = 'rgba(255,255,255,0.35)';   // 高光
  const hr = Math.max(1, s * 0.16);
  ctx.beginPath(); ctx.arc(x + pad + s * 0.32, y + pad + s * 0.3, hr, 0, Math.PI * 2); ctx.fill();
}
function roundRect(x, y, w, h, r) {
  ctx.beginPath();
  ctx.moveTo(x + r, y);
  ctx.arcTo(x + w, y, x + w, y + h, r);
  ctx.arcTo(x + w, y + h, x, y + h, r);
  ctx.arcTo(x, y + h, x, y, r);
  ctx.arcTo(x, y, x + w, y, r);
  ctx.closePath();
}

// ---- 分数平滑滚动（HUD 用 displayScore 追赶 score）----
let score = 0, displayScore = 0, best = 0;
function updateScoreDisplay(dt) {
  if (displayScore < score) {
    displayScore = Math.min(score, displayScore + (score - displayScore) * Math.min(1, dt * 12) + dt * 60);
  }
}
// HUD 绘制时用 Math.round(displayScore)；分数左上、最高分右上
```

### 7. 触摸交换：选中 + 拖拽方向判定（手机优先）

```javascript
let selected = null; // {r,c}

function pickCell(clientX, clientY) {
  const rect = canvas.getBoundingClientRect();
  const x = (clientX - rect.left) * canvas.width / rect.width / dpr;   // 换算到逻辑像素
  const y = (clientY - rect.top)  * canvas.height / rect.height / dpr;
  const c = Math.floor((x - originX) / cell);
  const r = Math.floor((y - originY) / cell);
  return inBounds(r, c) ? { r, c } : null;
}

// 在主流程里：只有相邻格才发起交换；交换无效则自动换回（resolveCascade 返回空步骤即无效）
function trySwap(a, b) {
  const adjacent = Math.abs(a.r - b.r) + Math.abs(a.c - b.c) === 1;
  if (!adjacent) { selected = b; return; }   // 不相邻则改选
  // 逻辑交换
  const ai = idx(a.r, a.c), bi = idx(b.r, b.c);
  const t = grid[ai]; grid[ai] = grid[bi]; grid[bi] = t;
  const steps = resolveCascade(grid);
  if (steps.length === 0) {                   // 无效：换回去（表现层应播放 swapBack 缓动）
    const t2 = grid[ai]; grid[ai] = grid[bi]; grid[bi] = t2;
    startSwapBackAnim(a, b);
  } else {
    startResolveAnim(a, b, steps);            // 逐层播放消除/下落 + 累加 score += scoreForStep(step)
  }
  selected = null;
}

canvas.addEventListener('touchstart', e => {
  e.preventDefault();
  if (state !== 'play') { resetGame(); return; }
  const cellHit = pickCell(e.touches[0].clientX, e.touches[0].clientY);
  if (cellHit) selected = cellHit;
}, { passive: false });

canvas.addEventListener('touchmove', e => {
  e.preventDefault();
  if (!selected) return;
  const cellHit = pickCell(e.touches[0].clientX, e.touches[0].clientY);
  if (cellHit && (cellHit.r !== selected.r || cellHit.c !== selected.c)) {
    trySwap(selected, cellHit);               // 拖到相邻格即触发
  }
}, { passive: false });
```

