## 1. 分层矢量角色（卡通/写实方向用；扁平/像素风跳过本节）

> 适用方向：cartoon / darkMood / warmFlat（有体积的角色）。**扁平极简用干净几何形状、像素风用像素网格画角色，不要套用本节的分层渐变描边**——那会破坏这两种风格。

一个有体积感的角色 = **落地椭圆阴影 + 后腿 + 身体（深浅渐变）+ 手臂 + 头 + 眼睛**，每层都带描边 outline。锚点统一放在**脚底中线**，方便落地与翻转。`facing` 用 `ctx.scale(f,1)` 实现左右翻转，不必写两套画法。

```javascript
function lerp(a, b, t) { return a + (b - a) * t; }

// 可换色：见第 5 节调色板
const PAL = {
  body: '#3a6ea5', bodyDark: '#28507a', bodyLight: '#5b93c9',
  outline: '#0d1b2a', skin: '#f2c9a0', skinDark: '#d9a878'
};

// 圆角矩形路径（身体用）
function roundRectPath(ctx, x, y, w, h, r) {
  r = Math.min(r, w / 2, h / 2);
  ctx.beginPath();
  ctx.moveTo(x + r, y);
  ctx.arcTo(x + w, y, x + w, y + h, r);
  ctx.arcTo(x + w, y + h, x, y + h, r);
  ctx.arcTo(x, y + h, x, y, r);
  ctx.arcTo(x, y, x + w, y, r);
  ctx.closePath();
}

// 脚下椭圆阴影（让角色「踩在地上」而不是飘着）
function ellipseShadow(ctx, x, y, rx, ry, alpha) {
  ctx.save();
  ctx.globalAlpha = alpha;
  ctx.fillStyle = 'rgba(0,0,0,0.45)';
  ctx.beginPath();
  ctx.ellipse(x, y, Math.max(1, rx), Math.max(1, ry), 0, 0, Math.PI * 2);
  ctx.fill();
  ctx.restore();
}

// c = {x(脚底中线), y(脚底), w, h, facing(1/-1),
//      pose:{breath, legSwing, armSwing, squash, lunge}}
function drawCharacter(ctx, c) {
  const p = c.pose || {};
  const breath   = p.breath   || 0;
  const legSwing = p.legSwing || 0;
  const armSwing = p.armSwing || 0;
  const squash   = p.squash   || 0;  // -1..1，负=压扁(落地)，正=拉伸(起跳)
  const lunge    = p.lunge    || 0;  // 0..1 攻击前冲
  const f = c.facing || 1;
  const w = c.w, h = c.h;

  const sx = 1 - squash * 0.25;      // 压扁时变宽
  const sy = 1 + squash * 0.25;      // 压扁时变矮

  // 落地阴影：起跳(squash>0)时缩小变淡
  const shAlpha = 0.5 - Math.max(0, squash) * 0.3;
  ellipseShadow(ctx, c.x, c.y + 2, w * 0.55 * sx, h * 0.12, shAlpha);

  ctx.save();
  // 锚点在脚底中线；前冲 lunge 推进；scale 的 f 实现左右翻转
  ctx.translate(c.x + f * lunge * w * 0.6, c.y + breath);
  ctx.scale(f * sx, sy);

  const lineW = Math.max(1, w * 0.06);
  ctx.lineJoin = 'round';
  ctx.lineCap = 'round';

  // ---- 双腿：相位相反摆动 ----
  const legLen = h * 0.34;
  for (let i = 0; i < 2; i++) {
    const dir = i === 0 ? 1 : -1;
    const sw = legSwing * dir;
    ctx.save();
    ctx.strokeStyle = PAL.outline;
    ctx.lineWidth = Math.max(1, w * 0.16);
    ctx.beginPath();
    ctx.moveTo(dir * w * 0.18, -legLen);
    ctx.lineTo(dir * w * 0.18 + sw * w * 0.4, 0);
    ctx.stroke();
    ctx.restore();
  }

  // ---- 身体：竖向深浅渐变(局部小渐变，性能安全) + 描边 ----
  const bodyTop = -h * 0.92, bodyH = h * 0.6;
  const bg = ctx.createLinearGradient(0, bodyTop, 0, bodyTop + bodyH);
  bg.addColorStop(0, PAL.bodyLight);
  bg.addColorStop(1, PAL.bodyDark);
  ctx.fillStyle = bg;
  ctx.strokeStyle = PAL.outline;
  ctx.lineWidth = lineW;
  roundRectPath(ctx, -w * 0.3, bodyTop, w * 0.6, bodyH, w * 0.18);
  ctx.fill();
  ctx.stroke();

  // ---- 前臂：摆动 + 攻击时抬起 ----
  const armLen = h * 0.3;
  const armA = armSwing + lunge * 0.8;
  ctx.save();
  ctx.strokeStyle = PAL.bodyDark;
  ctx.lineWidth = Math.max(1, w * 0.13);
  ctx.beginPath();
  ctx.moveTo(w * 0.22, bodyTop + bodyH * 0.25);
  ctx.lineTo(w * 0.22 + Math.sin(armA) * w * 0.3, bodyTop + bodyH * 0.25 + armLen);
  ctx.stroke();
  ctx.restore();

  // ---- 头 + 描边 ----
  const headR = w * 0.32, headCy = bodyTop - headR * 0.7;
  ctx.fillStyle = PAL.skin;
  ctx.strokeStyle = PAL.outline;
  ctx.lineWidth = lineW;
  ctx.beginPath();
  ctx.arc(0, headCy, Math.max(1, headR), 0, Math.PI * 2);
  ctx.fill();
  ctx.stroke();

  // ---- 眼睛(始终朝 facing 正向，因外层已翻转) ----
  ctx.fillStyle = PAL.outline;
  ctx.beginPath();
  ctx.arc(headR * 0.35, headCy - headR * 0.1, Math.max(1, headR * 0.12), 0, Math.PI * 2);
  ctx.fill();

  ctx.restore();
}
```

**要点**：
- **在卡通/写实方向下**，别用单个 `fillRect` 当角色/敌人——哪怕小怪也至少用「圆身体 + 圆眼睛 + 椭圆阴影 + 描边」3-4 层。（扁平极简方向例外：那里的角色本就是干净的几何色块，见 §0.5。）
- 黑色 `outline` 描边是卡通风「不廉价」的最高性价比手段。
- 渐变只在角色身体这种**小局部**用，且每帧重建无妨（区域小）；满屏大渐变才需要缓存（见第 3 节）。
- 小怪做法相同：把身体换成圆、加触角/尖牙等 1-2 个识别特征即可，复用 `ellipseShadow` 和描边。

