## 3. 深度与氛围背景（多层视差 + 渐变 + 雾 + 暗角）

满屏渐变是性能大头：**天空渐变、地面渐变、暗角全部缓存**，仅在 resize 时重建。

```javascript
// 天空垂直渐变：缓存返回值，别每帧建
function makeSkyGradient(ctx, H, top, bottom) {
  const g = ctx.createLinearGradient(0, 0, 0, H);
  g.addColorStop(0, top);
  g.addColorStop(1, bottom);
  return g;
}

// 多层视差远景剪影(山脉/楼群)。layer = {
//   color, speed(0近~1远, 越小越慢), span(单元宽), base(地平线比例),
//   shape:[[xFrac,yFrac]...] 一个起伏单元的轮廓点 }
function drawParallaxSilhouette(ctx, W, H, camX, layer) {
  ctx.save();
  ctx.fillStyle = layer.color;
  const off = -(camX * layer.speed) % layer.span;
  for (let i = -1; i < W / layer.span + 2; i++) {
    const bx = off + i * layer.span;
    ctx.beginPath();
    ctx.moveTo(bx, H * layer.base);
    for (const pt of layer.shape) ctx.lineTo(bx + pt[0] * layer.span, H * pt[1]);
    ctx.lineTo(bx + layer.span, H * layer.base);
    ctx.closePath();
    ctx.fill();
  }
  ctx.restore();
}

// 地面：缓存渐变填充 + 斜向纹理线(增加质感与速度感)
function drawGround(ctx, W, H, groundY, camX, lineColor, fillGrad) {
  ctx.fillStyle = fillGrad;                 // 传入缓存好的渐变
  ctx.fillRect(0, groundY, W, H - groundY);
  ctx.save();
  ctx.strokeStyle = lineColor;
  ctx.lineWidth = 1;
  ctx.globalAlpha = 0.25;
  const sp = 48;
  const off = -(camX) % sp;
  for (let x = off; x < W; x += sp) {
    ctx.beginPath();
    ctx.moveTo(x, groundY);
    ctx.lineTo(x - sp * 0.6, H);
    ctx.stroke();
  }
  ctx.restore();
}

// 雾/光带：横向半透明带，制造空气透视。grad 缓存(竖向 alpha 渐变)
function drawFogBand(ctx, W, y, h, grad) {
  ctx.save();
  ctx.fillStyle = grad;
  ctx.fillRect(0, y, W, h);
  ctx.restore();
}

// 屏幕暗角 vignette：缓存径向渐变(尺寸不变就复用)
let _vignette = null;
function getVignette(ctx, W, H) {
  if (_vignette && _vignette.w === W && _vignette.h === H) return _vignette.g;
  const g = ctx.createRadialGradient(W / 2, H / 2, H * 0.35, W / 2, H / 2, H * 0.8);
  g.addColorStop(0, 'rgba(0,0,0,0)');
  g.addColorStop(1, 'rgba(0,0,0,0.55)');
  _vignette = { w: W, h: H, g };
  return g;
}
function drawVignette(ctx, W, H) {
  ctx.save();
  ctx.fillStyle = getVignette(ctx, W, H);
  ctx.fillRect(0, 0, W, H);
  ctx.restore();
}
```

绘制顺序（从远到近）：天空渐变 → 远景剪影(speed 小) → 中景剪影 → 雾/光带 → 地面 → 实体/角色 → 暗角(最后盖在最上层)。

**要点**：
- 视差核心是 `camX * speed`：远层 speed 小（动得慢），近层 speed 大；`% span` 实现无缝循环。
- 远景剪影颜色用「天空底色 + 略暗」，自带空气透视感，别用纯黑。
- 暗角放在**所有内容之上最后画**，把四角压暗、聚焦中心，是「电影感」的廉价来源。

---

## 4. 光效与材质（发光 / 光晕 / 边缘光 / 霓虹）

`shadowBlur` 是 Canvas 内置辉光，最省事。**铁律：用完必须重置 `ctx.shadowBlur = 0`**，否则后续所有绘制都会拖一层模糊、且暴跌帧率。下面每个函数都用 `save/restore` 自动隔离，并再补一句 `shadowBlur=0` 双保险。

```javascript
// 发光光点(子弹/拾取物/灯)
function drawGlow(ctx, x, y, r, color) {
  ctx.save();
  ctx.shadowColor = color;
  ctx.shadowBlur = r * 0.8;
  ctx.fillStyle = color;
  ctx.beginPath();
  ctx.arc(x, y, Math.max(1, r * 0.4), 0, Math.PI * 2);
  ctx.fill();
  ctx.restore();        // restore 已清掉 shadowBlur
  ctx.shadowBlur = 0;   // 双保险
}

// 径向渐变光晕/爆炸核心(无 shadowBlur，更便宜)
function drawRadialBurst(ctx, x, y, r, c0, c1) {
  ctx.save();
  const g = ctx.createRadialGradient(x, y, 0, x, y, Math.max(1, r));
  g.addColorStop(0, c0);                    // 中心亮(如 'rgba(255,255,255,1)')
  g.addColorStop(0.5, c1);                  // 中段色
  g.addColorStop(1, 'rgba(0,0,0,0)');       // 边缘透明
  ctx.fillStyle = g;
  ctx.beginPath();
  ctx.arc(x, y, Math.max(1, r), 0, Math.PI * 2);
  ctx.fill();
  ctx.restore();
}

// 霓虹描边：双重描边 + shadowBlur 强化辉光
function drawNeonStroke(ctx, pathFn, color, width) {
  ctx.save();
  ctx.shadowColor = color;
  ctx.shadowBlur = 12;
  ctx.strokeStyle = color;
  ctx.lineWidth = width;
  ctx.lineJoin = 'round';
  pathFn(ctx);          // 由调用方画路径，如 ctx => roundRectPath(ctx,...)
  ctx.stroke();
  ctx.stroke();         // 二次描边让辉光更实
  ctx.restore();
  ctx.shadowBlur = 0;
}

// 边缘光 rim light：用 'lighter' 叠加，在角色受光侧描一段亮弧
function drawRimLight(ctx, x, y, r, color, side) {
  ctx.save();
  ctx.globalCompositeOperation = 'lighter';
  ctx.strokeStyle = color;
  ctx.lineWidth = Math.max(1, r * 0.18);
  ctx.beginPath();
  const a0 = side > 0 ? -Math.PI * 0.35 : Math.PI * 0.65;
  ctx.arc(x, y, Math.max(1, r), a0, a0 + Math.PI * 0.7);
  ctx.stroke();
  ctx.restore();        // restore 会还原 globalCompositeOperation
}
```

**要点**：
- 手机上 `shadowBlur` 不便宜：**只给少量关键元素用**（玩家、子弹、爆炸核心），背景大面积别用。
- 爆炸/能量优先用 `drawRadialBurst`（普通渐变），比 `shadowBlur` 快得多。
- `globalCompositeOperation='lighter'` 做发光叠加很出彩，但务必在 `save/restore` 内，别污染后续绘制。
- 凡是改了 `shadowBlur` / `globalAlpha` / `globalCompositeOperation`，都用 `save/restore` 包住。

